-- 外部キー。**両側の表のファイルに出す** —— 両方の表が在って、その列にまだ外部キーが無いときだけ張るので、先に当たった側は通り過ぎ、後から当たった側で張られる(相互参照する 2 表でも当たる)。既にある(名前が違っていても同じ列の)ものには触れない。
do $$
begin
    if to_regclass('public.holds') is not null and to_regclass('public.items') is not null then
        if not exists (
            select 1 from pg_constraint c
            where c.conrelid = 'public.holds'::regclass and c.contype = 'f'
              and pg_get_constraintdef(c.oid) like 'FOREIGN KEY (item_id)%'
        ) then
            alter table public.holds add constraint holds_item_id_fkey
                foreign key (item_id) references public.items (id) on delete no action;
        end if;
    end if;
end
$$;
do $$
begin
    if to_regclass('public.loans') is not null and to_regclass('public.items') is not null then
        if not exists (
            select 1 from pg_constraint c
            where c.conrelid = 'public.loans'::regclass and c.contype = 'f'
              and pg_get_constraintdef(c.oid) like 'FOREIGN KEY (item_id)%'
        ) then
            alter table public.loans add constraint loans_item_id_fkey
                foreign key (item_id) references public.items (id) on delete no action;
        end if;
    end if;
end
$$;

